:root {
  --bg: #0f172a;
  --card: #111827;
  --text: #e5e7eb;
  --muted: #9ca3af;
  --accent: #22c55e;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: linear-gradient(180deg, #0b1220, #0f172a);
  color: var(--text);
}
.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 16px;
}
h1 { margin: 0 0 6px; }
#welcome { margin: 0 0 12px; color: var(--muted); }
.card {
  background: var(--card);
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 14px;
  margin-bottom: 12px;
}
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}
button {
  width: 100%;
  border: none;
  background: #1f2937;
  color: var(--text);
  border-radius: 10px;
  padding: 12px;
  font-size: 15px;
}
button:active { transform: translateY(1px); }
label { display: block; margin: 8px 0; }
textarea {
  width: 100%;
  background: #0b1220;
  color: var(--text);
  border: 1px solid #374151;
  border-radius: 10px;
  padding: 10px;
}
.hint { color: var(--muted); font-size: 13px; }

